package com.example.examplemod.railway;

import com.example.examplemod.economy.EconomyManager;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.resources.ResourceLocation;

import java.util.List;
import java.util.Map;
import java.util.UUID;

public final class RailwayTripAccountingCheck {
    private static int checks;
    private static void require(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
    @SuppressWarnings("unchecked") private static Map<UUID,Long> balances(EconomyManager manager,String field)throws Exception{var f=EconomyManager.class.getDeclaredField(field);f.setAccessible(true);return(Map<UUID,Long>)f.get(manager);}
    private static void config()throws Exception{var field=com.example.examplemod.Config.class.getDeclaredField("SPEC");field.setAccessible(true);var spec=(net.neoforged.neoforge.common.ModConfigSpec)field.get(null);var data=com.electronwill.nightconfig.core.CommentedConfig.inMemory();spec.correct(data);data.set("items",List.of());var type=Class.forName("net.neoforged.fml.config.LoadedConfig");var ctor=type.getDeclaredConstructors()[0];ctor.setAccessible(true);spec.acceptConfig((net.neoforged.fml.config.IConfigSpec.ILoadedConfig)ctor.newInstance(data,null,null));}
    @SuppressWarnings("unchecked") private static <T> Map<UUID,T> map(RailwayManager manager,String field)throws Exception{var f=RailwayManager.class.getDeclaredField(field);f.setAccessible(true);return(Map<UUID,T>)f.get(manager);}
    public static void main(String[] args)throws Exception{
        config();EconomyManager economy=new EconomyManager();UUID payer=UUID.randomUUID(),owner=UUID.randomUUID(),trip=UUID.randomUUID();balances(economy,"treasuries").put(payer,1000L);
        require(economy.reserveTransport(trip,true,payer,300)&&economy.treasury(payer)==700,"reserve debits payer treasury");
        UUID insufficient=UUID.randomUUID();require(!economy.reserveTransport(insufficient,true,payer,800)&&economy.treasury(payer)==700,"insufficient funds block trip without debit");
        require(economy.settleTransport(trip,true,payer,300,List.of(new EconomyManager.TransportPayout(true,owner,180)))&&economy.treasury(payer)==820&&economy.treasury(owner)==180,"actual payout and reserve refund");
        require(!economy.settleTransport(trip,true,payer,300,List.of(new EconomyManager.TransportPayout(true,owner,180)))&&economy.treasury(owner)==180,"trip settlement is idempotent");
        RailwayManager manager=new RailwayManager();UUID networkId=UUID.randomUUID(),sectionId=UUID.randomUUID();var dimension=ResourceLocation.parse("minecraft:overworld");var n1=new RailwayNodeReference(dimension,0,128,0,0);var n2=new RailwayNodeReference(dimension,200,128,0,0);var edge=new RailwayEdgeReference(n1,n2).normalized();var endpoint=new RailwayEndpoint(UUID.randomUUID(),dimension,BlockPos.ZERO,dimension,BlockPos.ZERO,true,UUID.randomUUID(),edge,0);var network=new OwnedRailwayNetwork(networkId,RailwayOwnershipTypes.OwnerType.CITY,owner,"Foreign",RailwayOwnershipTypes.Access.PUBLIC,500);var section=new OwnedRailwaySection(sectionId,networkId,endpoint,endpoint,List.of(edge),100,RailwayOwnershipTypes.SectionStatus.ONLINE);map(manager,"ownedNetworks").put(networkId,network);map(manager,"ownedSections").put(sectionId,section);
        var legs=RailwayTripAccountingService.snapshotLegs(manager.ownedSections(),manager.ownedNetworks(),List.of(edge),100,RailwayOwnershipTypes.OwnerType.CITY,payer);require(legs.size()==1&&legs.getFirst().reservedAmount()==50,"CR per 1000 blocks tariff snapshot");network.freightTariff(900);network.access(RailwayOwnershipTypes.Access.PRIVATE);require(legs.getFirst().tariffPerThousandBlocks()==500&&legs.getFirst().reservedAmount()==50,"started trip keeps tariff and access snapshot");
        RailwayTripLedger active=new RailwayTripLedger(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),RailwayOwnershipTypes.OwnerType.CITY,payer,UUID.randomUUID(),UUID.randomUUID(),100,50,42,legs);active.progress(40);manager.addTrip(active);RouteReservation reservation=new RouteReservation(UUID.randomUUID(),active.id(),graphId(section),List.of(edge),legs);manager.addReservation(reservation);CompoundTag saved=manager.save(new CompoundTag(),null);var load=RailwayManager.class.getDeclaredMethod("load",CompoundTag.class,net.minecraft.core.HolderLookup.Provider.class);load.setAccessible(true);RailwayManager restored=(RailwayManager)load.invoke(null,saved,null);RailwayTripLedger resumed=restored.activeTrip(active.createTrainId());RouteReservation resumedRoute=restored.reservationForTrip(active.id());require(resumed!=null&&resumed.actualDistance()==40&&resumed.reservedAmount()==50&&resumed.legs().getFirst().tariffPerThousandBlocks()==500,"active reserve and snapshot survive restart");require(resumedRoute!=null&&resumedRoute.orderedEdges().equals(List.of(edge))&&resumedRoute.tariffSnapshot().getFirst().tariffPerThousandBlocks()==500,"ordered route and ownership snapshot survive restart");
        resumed.progress(100);require(resumed.actualCharge()==50&&resumed.close(RailwayTripLedger.Status.COMPLETED,99)&&!resumed.close(RailwayTripLedger.Status.INTERRUPTED,100),"completion and double-close protection");
        RailwayTripLedger interrupted=new RailwayTripLedger(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),RailwayOwnershipTypes.OwnerType.CITY,payer,UUID.randomUUID(),UUID.randomUUID(),100,50,1,legs);interrupted.progress(40);require(interrupted.actualCharge()==20&&interrupted.close(RailwayTripLedger.Status.INTERRUPTED,2),"interruption charges actual traversed length");
        require(RailwayTripAccountingService.snapshotLegs(List.of(section),List.of(new OwnedRailwayNetwork(networkId,RailwayOwnershipTypes.OwnerType.CITY,payer,"Own",RailwayOwnershipTypes.Access.PUBLIC,999)),List.of(edge),100,RailwayOwnershipTypes.OwnerType.CITY,payer).isEmpty(),"own infrastructure is free");
        var n3=new RailwayNodeReference(dimension,400,128,0,0);var second=new RailwayEdgeReference(n2,n3).normalized();RouteReservation guard=new RouteReservation(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),List.of(edge,second),legs);require(guard.observe(edge,true)==RouteReservation.Observation.ON_ROUTE,"guard accepts current edge");require(guard.observe(second,true)==RouteReservation.Observation.ADVANCED&&guard.cursor()==1,"guard advances ordered path");require(guard.observe(edge,true)==RouteReservation.Observation.REROUTED,"guard rejects turn-around outside remaining reservation");RouteReservation topology=new RouteReservation(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),List.of(edge),legs);require(topology.observe(edge,false)==RouteReservation.Observation.TOPOLOGY_CHANGED,"topology loss invalidates route");require(topology.close(RouteReservation.Status.ROUTE_INVALIDATED,5)&&!topology.close(RouteReservation.Status.CANCELLED,6),"reservation double-close rejected");
        UUID optionGraph=UUID.randomUUID(),destination=UUID.randomUUID();RailwayRouteOption cheap=new RailwayRouteOption(UUID.randomUUID(),RailwayRouteStrategy.CHEAPEST,optionGraph,destination,false,List.of(edge),120,10,200,List.of(),11),fast=new RailwayRouteOption(UUID.randomUUID(),RailwayRouteStrategy.FASTEST,optionGraph,destination,false,List.of(second),100,30,100,List.of(),12),balanced=new RailwayRouteOption(UUID.randomUUID(),RailwayRouteStrategy.BALANCED,optionGraph,destination,false,List.of(edge,second),110,18,140,List.of(),13);var strategies=RailwayRoutePlanner.selectStrategies(List.of(cheap,fast,balanced));require(strategies.size()==3&&strategies.get(0).strategy()==RailwayRouteStrategy.CHEAPEST&&strategies.get(1).strategy()==RailwayRouteStrategy.FASTEST&&strategies.get(2).strategy()==RailwayRouteStrategy.BALANCED,"cheapest fastest and normalized balanced selection");require(RailwayRoutePlanner.selectStrategies(List.of(cheap,new RailwayRouteOption(UUID.randomUUID(),RailwayRouteStrategy.FASTEST,optionGraph,destination,false,List.of(edge),120,10,200,List.of(),11))).size()==1,"duplicate paths collapse");
        OwnedRailwayNetwork privateForeign=new OwnedRailwayNetwork(UUID.randomUUID(),RailwayOwnershipTypes.OwnerType.CITY,owner,"Private",RailwayOwnershipTypes.Access.PRIVATE,0);require(!RailwayRoutePlanner.allowsNetwork(privateForeign,RailwayOwnershipTypes.OwnerType.CITY,payer)&&RailwayRoutePlanner.allowsNetwork(privateForeign,RailwayOwnershipTypes.OwnerType.CITY,owner),"foreign private excluded and owner allowed");require(RailwayRoutePlanner.selectionCurrent(cheap,optionGraph,destination,11)&&!RailwayRoutePlanner.selectionCurrent(cheap,optionGraph,destination,99),"stale topology fingerprint rejected");
        manager.proposeRoutes(active.fleetTrainId(),List.of(cheap));require(manager.selectRoute(active.fleetTrainId(),cheap.id(),123),"route selection accepted");CompoundTag selectedSaved=manager.save(new CompoundTag(),null);RailwayManager selectedRestored=(RailwayManager)load.invoke(null,selectedSaved,null);require(selectedRestored.selectedRoute(active.fleetTrainId())!=null&&selectedRestored.selectedRoute(active.fleetTrainId()).option().edges().equals(List.of(edge)),"selected route survives restart");
        System.out.println("PASS: "+checks+" railway reserve, settlement, restart and replay checks");
    }
    private static UUID graphId(OwnedRailwaySection section){return section.first().graphId();}
}
